package app.repositories;

import app.common.Page;
import app.entities.Note;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.stream.Stream;

/** Keeps notes rows in memory, for tests and for trying the services without a database. */
public class MemoryNoteRepository implements NoteRepository {
    private final Map<List<Object>, Note> rows = new LinkedHashMap<>();

    /** The key of a row, as a list of its key values. */
    private static List<Object> keyOf(Note row) {
        List<Object> key = new ArrayList<>();
        key.add(row.getId());
        return key;
    }

    /** Orders two keys value by value. */
    @SuppressWarnings({"unchecked", "rawtypes"})
    private static int compareKeys(List<Object> a, List<Object> b) {
        for (int index = 0; index < a.size(); index++) {
            int order = ((Comparable) a.get(index)).compareTo(b.get(index));
            if (order != 0) return order;
        }
        return 0;
    }

    private Stream<Note> visible() {
        return rows.values().stream().filter((row) -> true).sorted(Comparator.comparing(MemoryNoteRepository::keyOf, MemoryNoteRepository::compareKeys));
    }

    @Override
    public Optional<Note> findById(Integer id) {
        return visible().filter((row) -> Objects.equals(row.getId(), id)).findFirst();
    }

    @Override
    public Page<Note> list(int offset, int limit) {
        List<Note> rows = visible().toList();
        return new Page<>(rows.stream().skip(offset).limit(limit).toList(), rows.size(), offset, limit);
    }

    @Override
    public List<Note> listByAuthorId(Integer authorId) {
        return visible().filter((row) -> Objects.equals(row.getAuthorId(), authorId)).toList();
    }

    @Override
    public Note insert(Note entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public Note update(Note entity) {
        rows.put(keyOf(entity), entity);
        return entity;
    }

    @Override
    public void delete(Note entity) {
        rows.remove(keyOf(entity));
    }
}

