package app.services;

import app.UnitOfWork;
import app.common.Page;
import app.dtos.NoteCreate;
import app.dtos.NoteRead;
import app.dtos.NoteUpdate;
import app.entities.Note;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Operations on notes. Repositories commit every write. */
public class NoteService {
    private final UnitOfWork uow;

    public NoteService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "notes" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Note current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("id");
            if (value == null) {
                if (creating || values.containsKey("id")) errors.add(new FieldError("_id", "is required"));
            }
        }
        {
            Object value = values.get("text");
            if (value == null) {
                if (creating || values.containsKey("text")) errors.add(new FieldError("text", "is required"));
            }
        }
        {
            Object value = values.get("authorId");
            if (value == null) {
                if (creating || values.containsKey("authorId")) errors.add(new FieldError("authorId", "is required"));
            }
        }
        {
            Integer authorId = (Integer) (values.containsKey("authorId") ? values.get("authorId") : current == null ? null : current.getAuthorId());
            if (authorId != null && uow.users().findById(authorId).isEmpty())
                errors.add(new FieldError("authorId", "no User has this key"));
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Note", errors);
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Note current) {
        validate(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Note entity, Map<String, Object> values) {
        if (values.containsKey("id")) entity.setId((Integer) values.get("id"));
        if (values.containsKey("text")) entity.setText((String) values.get("text"));
        if (values.containsKey("authorId")) entity.setAuthorId((Integer) values.get("authorId"));
    }

    /** The Note with this key; NotFoundException when there is none. */
    private Note find(UnitOfWork uow, Integer id) {
        return uow.notes().findById(id).orElseThrow(() -> new NotFoundException("Note", id));
    }

    /** The Note as services return it. */
    private static NoteRead read(Note entity) {
        return new NoteRead(entity.getId(), entity.getText(), entity.getAuthorId());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(NoteUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.text() != null && changes.text().isPresent()) values.put("text", changes.text().value());
        if (changes.authorId() != null && changes.authorId().isPresent()) values.put("authorId", changes.authorId().value());
        return values;
    }

    /** Stores a new Note after checking it. */
    public NoteRead createNote(NoteCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.id() != null) values.put("id", data.id());
        if (data.text() != null) values.put("text", data.text());
        if (data.authorId() != null) values.put("authorId", data.authorId());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Note entity = new Note();
            apply(entity, values);
            return read(uow.notes().insert(entity));
        });
    }

    /** The Note with this key; NotFoundException when there is none. */
    public NoteRead getNote(Integer id) {
        return read(find(uow, id));
    }

    /** A page of notes, by primary key. */
    public Page<NoteRead> listNotes(int offset, int limit) {
        return uow.notes().list(offset, limit).map(NoteService::read);
    }

    /** Changes the given values of a Note. */
    public NoteRead updateNote(Integer id, NoteUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Note current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.notes().update(current));
        });
    }

    /** Deletes a Note. */
    public void deleteNote(Integer id) {
        uow.transaction((uow) -> {
            Note current = find(uow, id);
            uow.notes().delete(current);
            return null;
        });
    }

    /** The notes with this authorId. */
    public List<NoteRead> listNotesByAuthorId(Integer authorId) {
        return uow.notes().listByAuthorId(authorId).stream().map(NoteService::read).toList();
    }
}

