        Map<String, Object> values = new LinkedHashMap<>();
        if (data.id() != null) values.put("id", data.id());
        if (data.email() != null) values.put("email", data.email());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            User entity = new User();
            apply(entity, values);
            return read(uow.users().insert(entity));
        });
    }

    /** The User with this key; NotFoundException when there is none. */
    public UserRead getUser(Integer id) {
        return read(find(uow, id));
    }

    /** A page of users, by primary key. */
    public Page<UserRead> listUsers(int offset, int limit) {
