    }

    /** Changes the given values of a User. */
    public UserRead updateUser(Integer id, UserUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            User current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.users().update(current));
        });
    }

    /** Deletes a User. */
