        uow.transaction((uow) -> {
            User current = find(uow, id);
            if (!uow.notes().listByAuthorId(current.getId()).isEmpty()) throw new ConflictException("User", "rows of notes still point to it", List.of("notes"));
            uow.users().delete(current);
            return null;
        });
    }

    /** The User with this email, if there is one. */
