package app;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import app.common.Patch;
import app.dtos.UserCreate;
import app.dtos.UserUpdate;
import app.entities.User;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import app.services.UserService;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

/** Tests of the "users" table. */
class UserTest {
    /** The repositories over the test database, opened empty for every test */
    private MongoUnitOfWork uow;

    @BeforeEach
    void open() {
        uow = new MongoUnitOfWork(TestDatabase.open());
    }

    @Nested
    class Repository {

        @Test
        void isStoredAndReadBack() {
            User stored = Factories.addUser(uow, 1);
            User found = uow.users().findById(stored.getId()).orElseThrow();
            assertEquals(stored.getId(), found.getId());
            assertTrue(uow.users().findByEmail(stored.getEmail()).isPresent());
        }

        @Test
        void listsRowsByKey() {
            Factories.addUser(uow, 1);
            Factories.addUser(uow, 2);
            var page = uow.users().list(0, 1);
            assertEquals(2, page.total());
            assertEquals(1, page.items().size());
        }

        @Test
        void isDeleted() {
            User stored = Factories.addUser(uow, 1);
            uow.users().delete(stored);
            assertTrue(uow.users().findById(stored.getId()).isEmpty());
        }
    }

    @Nested
    class UserServiceTest {
        private final MemoryUnitOfWork uow = new MemoryUnitOfWork();

        @Test
        void createsAValidRow() {
            UserService service = new UserService(uow);
            int n = 100;
            User row = Factories.newUser(1);
            var created = service.createUser(createOf(row));
            var found = service.getUser(created.id());
            assertEquals(created.id(), found.id());
        }

        @Test
        void refusesAMissingValue() {
            UserService service = new UserService(uow);
            int n = 100;
            User row = Factories.newUser(1);
            row.setId(null);
            ValidationFailedException error = assertThrows(ValidationFailedException.class, () -> service.createUser(createOf(row)));
            assertEquals(List.of("_id"), error.getErrors().stream().map(FieldError::field).toList());
        }

        @Test
        void refusesARepeatedUniqueValue() {
            UserService service = new UserService(uow);
            int n = 100;
            User row = Factories.newUser(1);
            var first = service.createUser(createOf(row));
            User again = Factories.newUser(2);
            again.setEmail(first.email());
            assertThrows(ConflictException.class, () -> service.createUser(createOf(again)));
        }

        @Test
        void keepsItsOwnUniqueValue() {
            UserService service = new UserService(uow);
            int n = 100;
            User row = Factories.newUser(1);
            var created = service.createUser(createOf(row));
            service.updateUser(created.id(), new UserUpdate(Patch.of(created.email())));
        }

        @Test
        void saysWhenARowIsMissing() {
            UserService service = new UserService(uow);
            assertThrows(NotFoundException.class, () -> service.getUser(999999));
        }

        @Test
        void deletesARow() {
            UserService service = new UserService(uow);
            int n = 100;
            User row = Factories.newUser(1);
            var created = service.createUser(createOf(row));
            service.deleteUser(created.id());
            assertThrows(NotFoundException.class, () -> service.getUser(created.id()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static UserCreate createOf(User row) {
        return new UserCreate(row.getId(), row.getEmail());
    }
}
